// Original test-only NES NROM-128 program. Source and generated bytes: CC0-1.0.
// No external ROM, firmware, assembler, or filesystem writes are needed.
// A rising edge of controller A increments battery RAM at $6002. The program
// reads that byte every frame to select its backdrop, including after restore.
export function buildNesBatteryFixture() {
  const code = []
  const labels = new Map()
  const fixups = []
  const emit = (...bytes) => code.push(...bytes)
  const label = name => labels.set(name, 0x8000 + code.length)
  const absolute = (opcode, name) => { emit(opcode, 0, 0); fixups.push({ at: code.length - 2, name }) }
  const branch = (opcode, name) => { emit(opcode, 0); fixups.push({ at: code.length - 1, name, relative: true }) }

  label('reset')
  emit(0x78, 0xd8, 0xa2, 0xff, 0x9a) // SEI; CLD; LDX #$ff; TXS
  emit(0xa9, 0, 0x8d, 0, 0x20, 0x8d, 1, 0x20, 0x8d, 0x10, 0x40, 0x85, 0) // disable PPU/APU IRQ; last A = 0
  label('wait1'); emit(0x2c, 2, 0x20); branch(0x10, 'wait1')
  label('wait2'); emit(0x2c, 2, 0x20); branch(0x10, 'wait2')
  emit(0xad, 0, 0x60, 0xc9, 0x4d); branch(0xd0, 'initialize') // magic 'M'
  emit(0xad, 1, 0x60, 0xc9, 0x44); branch(0xf0, 'frame') // magic 'D'
  label('initialize')
  emit(0xa9, 0x4d, 0x8d, 0, 0x60, 0xa9, 0x44, 0x8d, 1, 0x60, 0xa9, 0, 0x8d, 2, 0x60)

  label('frame')
  emit(0x2c, 2, 0x20); branch(0x10, 'frame') // wait for vblank
  emit(0xa9, 1, 0x8d, 0x16, 0x40, 0xa9, 0, 0x8d, 0x16, 0x40) // latch controller
  emit(0xad, 0x16, 0x40, 0x29, 1); branch(0xf0, 'released')
  emit(0xa5, 0); branch(0xd0, 'draw') // held A must not increment again
  emit(0xee, 2, 0x60, 0xa9, 1, 0x85, 0); absolute(0x4c, 'draw')
  label('released'); emit(0x85, 0) // A is zero
  label('draw')
  emit(0xa9, 0, 0x8d, 1, 0x20) // rendering off while writing palette
  emit(0xa9, 0x3f, 0x8d, 6, 0x20, 0xa9, 0, 0x8d, 6, 0x20)
  emit(0xad, 2, 0x60, 0x29, 3, 0xaa); absolute(0xbd, 'colors') // LDA colors,X
  emit(0x8d, 7, 0x20)
  emit(0xa9, 0, 0x8d, 6, 0x20, 0x8d, 6, 0x20, 0x8d, 5, 0x20, 0x8d, 5, 0x20)
  emit(0xa9, 0x0a, 0x8d, 1, 0x20); absolute(0x4c, 'frame')
  label('irq'); emit(0x40)
  label('colors'); emit(0x0f, 0x16, 0x2a, 0x12) // black, red, green, blue

  for (const fixup of fixups) {
    const target = labels.get(fixup.name)
    if (target === undefined) throw new Error('Unknown label: ' + fixup.name)
    if (fixup.relative) {
      const delta = target - (0x8000 + fixup.at + 1)
      if (delta < -128 || delta > 127) throw new Error('Branch out of range: ' + fixup.name)
      code[fixup.at] = delta & 255
    } else {
      code[fixup.at] = target & 255
      code[fixup.at + 1] = target >> 8
    }
  }
  const prg = Buffer.alloc(16384, 0xea)
  Buffer.from(code).copy(prg)
  for (const [offset, name] of [[0x3ffa, 'irq'], [0x3ffc, 'reset'], [0x3ffe, 'irq']]) prg.writeUInt16LE(labels.get(name), offset)
  // iNES mapper 0, 16 KiB PRG, 8 KiB CHR, battery flag, 8 KiB PRG RAM.
  const header = Buffer.from([0x4e, 0x45, 0x53, 0x1a, 1, 1, 2, 0, 1, 0, 0, 0, 0, 0, 0, 0])
  return Buffer.concat([header, prg, Buffer.alloc(8192)])
}
